<?php
namespace App\Services;
use App\Models\{BusinessSetting,Order};
use Illuminate\Support\Facades\{DB,Crypt,Http,Cache};
class StoreOperations {
 public static function get($key,$default=[]){$key=SteadfastAccounts::storageKey($key);$raw=BusinessSetting::where('type','ops_'.$key)->value('value');if(!$raw)return $default;try{return json_decode(Crypt::decryptString($raw),true)??$default;}catch(\Throwable $e){throw new \RuntimeException('Operations settings cannot be decrypted. Keep the original APP_KEY.');}}
 public static function put($key,$value){$key=SteadfastAccounts::storageKey($key);$row=BusinessSetting::where('type','ops_'.$key)->first()?:new BusinessSetting();$row->type='ops_'.$key;$row->value=Crypt::encryptString(json_encode($value,JSON_UNESCAPED_UNICODE));$row->save();Cache::forget('ops_'.$key);}
 public static function audit($action,$order=null){$events=self::get('audit');$events[]=['action'=>$action,'order_id'=>$order,'admin_id'=>auth()->id(),'at'=>now()->toIso8601String()];self::put('audit',array_slice($events,-200));}
 public static function settings(){return SteadfastAccounts::credentials(SteadfastAccounts::current());}
 public static function shipment($id){return self::get('shipment_'.(int)$id);}
 private static function client(){ $c=self::settings();abort_unless($c['mode']==='live'&&!empty($c['api_key'])&&!empty($c['secret_key']),422,'Set Steadfast live credentials first.');return Http::withHeaders(['Api-Key'=>$c['api_key'],'Secret-Key'=>$c['secret_key']])->acceptJson()->withOptions(['connect_timeout'=>5,'allow_redirects'=>false])->timeout(20);}
 public static function send($id,$account='legacy'){return SteadfastAccounts::using($account,function()use($id){abort_unless(SteadfastAccounts::credentials(SteadfastAccounts::current())['active'],409,'Courier account is disabled.');return self::sendInAccount($id);});}
 private static function sendInAccount($id){
  $reservation=DB::transaction(function()use($id){$order=Order::whereKey($id)->lockForUpdate()->firstOrFail();abort_if(in_array($order->delivery_status,['cancelled','delivered']),409,'This order cannot be booked.');$settings=self::settings();$mock=$settings['mode']!=='live';$old=self::shipment($id);abort_if(in_array($old['state']??'', ['booked','sending','uncertain'])&&!(($old['mock']??false)&&!$mock),409,'Already booked or awaiting reconciliation. Sync/check Steadfast before trying again.');$a=json_decode($order->shipping_address,true)?:[];$phone=preg_replace('/\D/','',$a['phone']??'');if(strpos($phone,'880')===0)$phone=substr($phone,2);abort_unless(preg_match('/^01[3-9][0-9]{8}$/',$phone)&&!empty($a['name'])&&!empty($a['address']),422,'Valid recipient name, mobile and address required.');$payload=['invoice'=>'FS-'.$id,'recipient_name'=>$a['name'],'recipient_phone'=>$phone,'recipient_address'=>implode(', ',array_filter([$a['address'],$a['city']??''])),'cod_amount'=>$order->payment_status==='paid'?0:round($order->grand_total,2),'note'=>AdminDeliveryNote::text($order->id),'item_description'=>CourierLabel::description($order)];if(!$mock)abort_unless(!empty($settings['api_key'])&&!empty($settings['secret_key']),422,'Set live API credentials first.');$attempt=bin2hex(random_bytes(16));DB::table('orders')->where('id',$id)->update(['courier_reservation_token'=>$attempt]);self::put('shipment_'.$id,['state'=>'sending','mock'=>$mock,'invoice'=>$payload['invoice'],'attempt'=>$attempt,'account_id'=>SteadfastAccounts::current(),'account_label'=>SteadfastAccounts::credentials(SteadfastAccounts::current())['label']]);return compact('payload','mock','attempt');},3);
  // Commit the reservation BEFORE the network request; a killed PHP process leaves a blocked sending record.
  extract($reservation);try{if($mock)$data=['status'=>200,'consignment'=>['consignment_id'=>'mock-'.$id,'tracking_code'=>'MOCK-'.$id,'status'=>'in_review']];else{$response=self::client()->post(SteadfastApi::BASE_URL.'/create_order',$payload);$data=$response->json();if(!$response->successful()||($data['status']??0)!==200||empty($data['consignment']['consignment_id']))throw new \RuntimeException('Courier booking response uncertain.');}$c=$data['consignment'];DB::transaction(function()use($id,$mock,$attempt,$payload,$c){$order=Order::whereKey($id)->lockForUpdate()->firstOrFail();abort_unless((self::shipment($id)['attempt']??null)===$attempt,409,'Shipment reservation changed.');self::put('shipment_'.$id,['state'=>'booked','account_id'=>SteadfastAccounts::current(),'account_label'=>SteadfastAccounts::credentials(SteadfastAccounts::current())['label'],'recipient_name'=>$payload['recipient_name'],'recipient_phone'=>$payload['recipient_phone'],'recipient_address'=>$payload['recipient_address'],'cod_amount'=>$payload['cod_amount'],'item_description'=>$payload['item_description'],'invoice'=>$payload['invoice'],'consignment_id'=>(string)$c['consignment_id'],'tracking_code'=>$c['tracking_code']??'','status'=>$c['status']??'in_review','mock'=>$mock,'synced_at'=>now()->toIso8601String()]);if(!$mock)\App\Services\DeliveryActivity::record($id,'booked',self::shipment($id));if(!$mock&&$order->delivery_status==='pending'){$order->delivery_status='confirmed';$order->save();$order->orderDetails()->update(['delivery_status'=>'confirmed']);\App\Utility\NotificationUtility::sendNotification($order,'confirmed');}self::audit('steadfast_booked',$id);});return ['ok'=>true,'mock'=>$mock];}catch(\Throwable $e){$current=self::shipment($id);if(($current['state']??'')==='sending'){$current['state']='uncertain';self::put('shipment_'.$id,$current);}return ['ok'=>false,'message'=>'Booking response uncertain; do not resend. Sync/check courier portal to prevent duplicate parcels.'];}
 }
 public static function sync($id,$history=false){$parcel=self::shipment($id);if(($parcel['provider']??'')==='carrybee')return CarryBee::sync($id);abort_unless($parcel,422,'No shipment to sync.');return SteadfastAccounts::using($parcel['account_id']??'legacy',function()use($id,$history){return self::syncInAccount($id,$history);});}
 private static function syncInAccount($id,$history=false){$s=self::shipment($id);abort_unless($s,422,'No shipment to sync.');if($s['mock']??false)return $s;$path=!empty($s['consignment_id'])?'status_by_cid/'.rawurlencode($s['consignment_id']):'status_by_invoice/'.rawurlencode($s['invoice']);$r=self::client()->get(SteadfastApi::BASE_URL.'/'.$path);$d=$r->json();abort_unless($r->successful()&&($d['status']??0)===200&&isset($d['delivery_status']),502,'Courier sync failed; current order unchanged.');self::applyStatus($id,(string)$d['delivery_status'],$history);return self::shipment($id);}
 public static function applyStatus($id,$status,$history=false,$rawStatus=null){
  $known=['pending','delivered_approval_pending','partial_delivered_approval_pending','cancelled_approval_pending','unknown_approval_pending','delivered','partial_delivered','cancelled','hold','in_review','unknown'];
  abort_unless(in_array($status,$known,true),422,'Unknown courier status.');
  DB::transaction(function()use($id,$status,$history,$rawStatus){
   $o=Order::whereKey($id)->lockForUpdate()->firstOrFail();$s=self::shipment($id);
   $historical=$history||(($s['linked_by']??'')==='exact_invoice');
   $previousCourierStatus=$s['status']??null;
   $s['status']=$rawStatus??$status;if($status==='partial_delivered')$s['cancellation_type']='partial';elseif($status==='cancelled'&&($s['cancellation_type']??null)!=='partial')$s['cancellation_type']='standard';elseif($status==='delivered')unset($s['cancellation_type']);$s['synced_at']=now()->toIso8601String();
   $map=['delivered'=>'delivered','cancelled'=>'cancelled','partial_delivered'=>'cancelled'];$changed=false;$deliveryChanged=false;
   if(isset($map[$status])&&$o->delivery_status!==$map[$status]){
    $o->delivery_status=$map[$status];$changed=true;$deliveryChanged=true;
    if($status==='cancelled'&&!$historical)foreach($o->orderDetails as$detail)\App\Models\ProductStock::where('product_id',$detail->product_id)->where('variant',$detail->variation?:'')->increment('qty',$detail->quantity);
    $o->orderDetails()->update(['delivery_status'=>$map[$status]]);
   }
   if($status==='delivered'&&$o->payment_type==='cash_on_delivery'&&$o->payment_status==='unpaid'){
    $o->payment_status='paid';$o->orderDetails()->update(['payment_status'=>'paid']);
    $s['payment_basis']='courier_delivered_cod';$s['payment_verified_at']=now()->toIso8601String();$changed=true;
   }
   if($changed)$o->save();self::put('shipment_'.$id,$s);CourierOrderStatus::forget($id);if($changed)DB::afterCommit(function(){CourierOrderStatus::invalidateReports();});
   \App\Services\DeliveryActivity::record($id,'booked',$s,true);
   if(isset($map[$status]))\App\Services\DeliveryActivity::record($id,$map[$status],$s,$historical&&(!$previousCourierStatus||$previousCourierStatus===$status));
   if($deliveryChanged&&(!$historical||($previousCourierStatus&&$previousCourierStatus!==$status))&&isset($map[$status]))\App\Utility\NotificationUtility::sendNotification($o,$map[$status]);
   // Historical reconciliation changes reports only: no stock movements, old SMS or refund.
   // Paid here means delivered COD, not that courier settlement reached the merchant bank.
  });
 }
 public static function edit($id,$d){return DB::transaction(function()use($id,$d){
 $o=Order::whereKey($id)->lockForUpdate()->firstOrFail();abort_if(in_array($o->delivery_status,['delivered','cancelled']),409,'Completed/cancelled order cannot be edited.');$shipment=self::shipment($id);abort_if($shipment&&!(bool)($shipment['mock']??false),409,'Courier already received this order. Edit in courier portal first; local edits would not update their parcel.');
 $details=$o->orderDetails()->with('product.stocks')->get();$remove=array_values(array_unique(array_map('intval',$d['remove_ids']??[])));abort_if(array_diff($remove,$details->pluck('id')->all()),422,'Remove only products from this invoice.');abort_if(count($remove)>=$details->count(),422,'Keep at least one product, or use Cancel order.');abort_if($remove&&$o->payment_status==='paid',409,'Paid invoice product removal requires a refund/reconciliation workflow. No refund is made here.');
 $address=json_decode($o->shipping_address,true)?:[];foreach(['name','phone','address','city']as $key)$address[$key]=$d[$key];$o->shipping_address=json_encode($address);$remaining=collect();
 foreach($details as $line){$oldQty=(int)$line->quantity;if(in_array($line->id,$remove,true)){\App\Models\ProductStock::where('product_id',$line->product_id)->where('variant',$line->variation?:'')->increment('qty',$oldQty);$line->delete();continue;}
 $input=$d['lines'][$line->id]??null;abort_unless($input&&isset($input['quantity'],$input['stock_id']),422,'Size and quantity are required for every retained product.');$qty=(int)$input['quantity'];$stock=($line->product ? $line->product->stocks->firstWhere('id',(int)$input['stock_id']) : null);abort_unless($stock&&$qty>=max(1,(int)$line->product->min_qty)&&$qty<=99,422,'Choose a valid size/quantity.');$oldStock=\App\Models\ProductStock::where('product_id',$line->product_id)->where('variant',$line->variation?:'')->lockForUpdate()->first();$stock=\App\Models\ProductStock::whereKey($stock->id)->lockForUpdate()->firstOrFail();$available=(int)$stock->qty+($oldStock&&$oldStock->id===$stock->id?$oldQty:0);abort_unless($available>=$qty,422,'Selected size does not have enough stock.');if($oldStock)\App\Models\ProductStock::whereKey($oldStock->id)->increment('qty',$oldQty);\App\Models\ProductStock::whereKey($stock->id)->decrement('qty',$qty);$unit=$oldQty>0?(float)$line->price/$oldQty:0;$taxUnit=$oldQty>0?(float)$line->tax/$oldQty:0;if(!empty($d['_customer_edit'])){$quote=\App\Services\Checkout\ProductQuote::selection($line->product,$stock,$qty);$unit=$quote['price'];$taxUnit=$quote['tax'];}
 $line->variation=$stock->variant;$line->quantity=$qty;$line->price=round($unit*$qty,2);$line->tax=round($taxUnit*$qty,2);$line->shipping_cost=0;$line->save();$remaining->push($line);}
 $remaining->first()->shipping_cost=$d['delivery_charge'];$remaining->first()->save();$addonTotal=\App\Services\ProductAddons::reconcile($o->id);$subtotal=$addonTotal+$remaining->sum('price')+$remaining->sum('tax')+(float)$d['delivery_charge'];abort_if($subtotal<(float)$o->coupon_discount,422,'Discount exceeds updated total.');$o->grand_total=round($subtotal-(float)$o->coupon_discount,2);$o->save();$combined=\App\Models\CombinedOrder::find($o->combined_order_id);if($combined){if(Order::where('combined_order_id',$combined->id)->count()===1)$combined->shipping_address=$o->shipping_address;$combined->grand_total=Order::where('combined_order_id',$combined->id)->sum('grand_total');$combined->save();}self::audit('invoice_edited'.($remove?':removed:'.implode(',',$remove):''),$id);return $o;
 });}
 public static function cancel($id){return DB::transaction(function()use($id){$o=Order::whereKey($id)->lockForUpdate()->firstOrFail();abort_if($o->delivery_status==='delivered',409,'Delivered order cannot be cancelled here.');$s=self::shipment($id);abort_if($s&&!(bool)($s['mock']??false),409,'Parcel exists at courier. Cancel/resolve it in Steadfast portal first; local cancel does not cancel courier.');if($o->delivery_status!=='cancelled'){$o->delivery_status='cancelled';$o->save();foreach($o->orderDetails as $detail){\App\Models\ProductStock::where('product_id',$detail->product_id)->where('variant',$detail->variation?:'')->increment('qty',$detail->quantity);}$o->orderDetails()->update(['delivery_status'=>'cancelled']);\App\Utility\NotificationUtility::sendNotification($o,'cancelled');self::audit('order_cancelled',$id);}return $o;});}
}

